package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StopWatch_stop_TriageGen3Test {

    @Test
    public void testStop_WhenRunning_ShouldStopSuccessfully() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();

        stopWatch.stop();

        // Verify state transition (though state field is private, 
        // we can infer success if no exception is thrown and we check timing behavior)
        assertTrue("StopWatch should have recorded a stop time", stopWatch.getTime() >= 0);
    }

    @Test
    public void testStop_WhenSuspended_ShouldStopSuccessfully() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.suspend();

        stopWatch.stop();

        assertTrue("StopWatch should allow stopping from suspended state", stopWatch.getTime() >= 0);
    }

    @Test(expected = IllegalStateException.class)
    public void testStop_WhenNotRunning_ShouldThrowException() {
        StopWatch stopWatch = new StopWatch();
        // State is initially STATE_STOPPED (not running, not suspended)
        stopWatch.stop();
    }

    @Test(expected = IllegalStateException.class)
    public void testStop_WhenAlreadyStopped_ShouldThrowException() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.stop();

        // Second stop should trigger IllegalStateException
        stopWatch.stop();
    }

    @Test
    public void testStop_AfterReset_ShouldThrowException() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.reset();

        try {
            stopWatch.stop();
            fail("Expected IllegalStateException to be thrown");
        } catch (IllegalStateException e) {
            assertEquals("Stopwatch is not running. ", e.getMessage());
        }
    }
}
